 phen=['<span class="months">Mar\u2013Apr</span> \U0001f438 <b>Moor frogs</b> call in the bog hollows.',
       '<span class="months">May\u2013Jun</span> \U0001f33f <b>Hare\u2019s-tail cottongrass</b> sets white plumes.',
       '<span class="months">Jul\u2013Aug</span> \U0001f33f <b>Sundew</b> catches insects; cranberry flowers.',
       '<span class="months">Sep\u2013Oct</span> \U0001f7e5 <b>Bog-moss cushions</b> turn deep red.'],
